`timescale 1ns / 1ps
// Generated by pipeline/make_tasks.py (sign-off). Reference: golden/reference (priority_encoder__ref below).
module tb;
  reg tb_clk; integer tb_seed, tb_cyc, tb_mis, tb_perr, tb_b, tb_k, tb_ph; reg tb_started; reg [31:0] tb_r;
  reg reset;
  reg en;
  reg in0;
  reg in1;
  reg in2;
  reg in3;
  wire [0:0] out0; wire [0:0] ref_out0;
  wire [0:0] out1; wire [0:0] ref_out1;
  wire [0:0] out2; wire [0:0] ref_out2;
  wire [0:0] out3; wire [0:0] ref_out3;
  wire clk = tb_clk;
  priority_encoder dut (.reset(reset), .en(en), .in0(in0), .in1(in1), .in2(in2), .in3(in3), .out0(out0), .out1(out1), .out2(out2), .out3(out3), .clk(clk));
  priority_encoder__ref ref_i (.reset(reset), .en(en), .in0(in0), .in1(in1), .in2(in2), .in3(in3), .out0(ref_out0), .out1(ref_out1), .out2(ref_out2), .out3(ref_out3), .clk(clk));
  always #5 tb_clk = ~tb_clk;
  function [31:0] tb_rand(input integer dummy); begin tb_rand = $random(tb_seed); end endfunction
  // flit: type in [30:29], VC in [28:27], destination row/column 0..3 in [7:4]/[3:0]
  function [31:0] tb_flit(input integer dummy); reg [31:0] r; begin r = $random(tb_seed);
    tb_flit = {1'b0, r[30:29], r[28:27], r[26:8], 2'b00, r[5:4], 2'b00, r[1:0]}; end endfunction
  task tb_prop(input [8*64:1] msg); begin tb_perr = tb_perr + 1;
    if (tb_perr <= 15) $display("FAIL property: %0s (t=%0t)", msg, $time); end endtask
  task tb_compare; begin
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1)
      if (ref_out0[tb_b] !== 1'bx && ref_out0[tb_b] !== 1'bz && out0[tb_b] !== ref_out0[tb_b]) begin
        tb_mis = tb_mis + 1; tb_b = 1;
        if (tb_mis <= 15) $display("FAIL t=%0t cycle %0d: out0 = %h, expected %h", $time, tb_cyc, out0, ref_out0);
      end
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1)
      if (ref_out1[tb_b] !== 1'bx && ref_out1[tb_b] !== 1'bz && out1[tb_b] !== ref_out1[tb_b]) begin
        tb_mis = tb_mis + 1; tb_b = 1;
        if (tb_mis <= 15) $display("FAIL t=%0t cycle %0d: out1 = %h, expected %h", $time, tb_cyc, out1, ref_out1);
      end
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1)
      if (ref_out2[tb_b] !== 1'bx && ref_out2[tb_b] !== 1'bz && out2[tb_b] !== ref_out2[tb_b]) begin
        tb_mis = tb_mis + 1; tb_b = 1;
        if (tb_mis <= 15) $display("FAIL t=%0t cycle %0d: out2 = %h, expected %h", $time, tb_cyc, out2, ref_out2);
      end
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1)
      if (ref_out3[tb_b] !== 1'bx && ref_out3[tb_b] !== 1'bz && out3[tb_b] !== ref_out3[tb_b]) begin
        tb_mis = tb_mis + 1; tb_b = 1;
        if (tb_mis <= 15) $display("FAIL t=%0t cycle %0d: out3 = %h, expected %h", $time, tb_cyc, out3, ref_out3);
      end
  end endtask
  task tb_props; begin
    if (tb_started) begin
      if (^{out0, out1, out2, out3} === 1'bx || (out0 + out1 + out2 + out3) > 1) tb_prop("out not one-hot-or-zero");
    end
  end endtask
  reg [0:0] tbc_p_out0, tbc_t_out0;
  reg [0:0] tbc_p_out1, tbc_t_out1;
  reg [0:0] tbc_p_out2, tbc_t_out2;
  reg [0:0] tbc_p_out3, tbc_t_out3;
  integer tbc_outs, tbc_bits;
  task tb_cov; begin
    if (tb_cyc > 6 || tb_ph == 1) tbc_t_out0 = tbc_t_out0 | ((ref_out0 ^ tbc_p_out0) & ~(ref_out0 ^ ref_out0)); tbc_p_out0 = ref_out0;
    if (tb_cyc > 6 || tb_ph == 1) tbc_t_out1 = tbc_t_out1 | ((ref_out1 ^ tbc_p_out1) & ~(ref_out1 ^ ref_out1)); tbc_p_out1 = ref_out1;
    if (tb_cyc > 6 || tb_ph == 1) tbc_t_out2 = tbc_t_out2 | ((ref_out2 ^ tbc_p_out2) & ~(ref_out2 ^ ref_out2)); tbc_p_out2 = ref_out2;
    if (tb_cyc > 6 || tb_ph == 1) tbc_t_out3 = tbc_t_out3 | ((ref_out3 ^ tbc_p_out3) & ~(ref_out3 ^ ref_out3)); tbc_p_out3 = ref_out3;
  end endtask
  task tb_cov_report; begin tbc_outs = 0; tbc_bits = 0;
    if (|tbc_t_out0) tbc_outs = tbc_outs + 1;
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1) if (tbc_t_out0[tb_b] === 1'b1) tbc_bits = tbc_bits + 1;
    if (|tbc_t_out1) tbc_outs = tbc_outs + 1;
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1) if (tbc_t_out1[tb_b] === 1'b1) tbc_bits = tbc_bits + 1;
    if (|tbc_t_out2) tbc_outs = tbc_outs + 1;
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1) if (tbc_t_out2[tb_b] === 1'b1) tbc_bits = tbc_bits + 1;
    if (|tbc_t_out3) tbc_outs = tbc_outs + 1;
    for (tb_b = 0; tb_b < 1; tb_b = tb_b + 1) if (tbc_t_out3[tb_b] === 1'b1) tbc_bits = tbc_bits + 1;
    $display("INFO coverage: %0d of 4 checked outputs toggled, %0d of 4 bits", tbc_outs, tbc_bits);
  end endtask
  initial begin
    tb_seed = 29; tb_clk = 0; tb_mis = 0; tb_perr = 0; tb_started = 0; tb_ph = 0; tb_k = 0;
    reset = 0; en = 0; in0 = 0; in1 = 0; in2 = 0; in3 = 0; reset = 1;
    tbc_t_out0 = 0; tbc_p_out0 = 0; tbc_t_out1 = 0; tbc_p_out1 = 0; tbc_t_out2 = 0; tbc_p_out2 = 0; tbc_t_out3 = 0; tbc_p_out3 = 0;
    for (tb_cyc = 0; tb_cyc < 5000; tb_cyc = tb_cyc + 1) begin
      @(negedge tb_clk);
      reset = (tb_cyc < 4) ? 1'b1 : (tb_rand(0) % 40 == 0);
      en = {tb_rand(0)};
      if (tb_rand(0) % 6 == 0) in0 = ~in0;
      if (tb_rand(0) % 6 == 0) in1 = ~in1;
      if (tb_rand(0) % 6 == 0) in2 = ~in2;
      if (tb_rand(0) % 6 == 0) in3 = ~in3;
      tb_started = (tb_cyc >= 6);
      #4 tb_ph = 0; tb_compare; tb_props; if (tb_started) tb_cov;
      @(posedge tb_clk); #4 tb_ph = 1; tb_compare; tb_props; if (tb_started) tb_cov;
    end
    tb_cov_report;
    if (tb_mis + tb_perr == 0) $display("ALL TESTS PASSED");
    else $display("FAIL: %0d mismatches, %0d property errors", tb_mis, tb_perr);
    $finish;
  end
endmodule

// ---- reference copy of the golden module (children come from lib/)
`timescale 1ns / 1ps





















module priority_encoder__ref(reset,en,in0,in1,in2,in3,out0,out1,out2,out3,clk);
input reset;
input en,in0,in1,in2,in3;
output reg out0,out1,out2,out3;
reg r0,r1,r2,r3;
input clk;

always@(posedge clk)
begin
 r0=in0 & !out1 & !out2 & !out3;
 r1=in1 & !out0 & !out2 & !out3;
 r2=in2 & !out0 & !out1 & !out3;
 r3=in3 & !out0 & !out1 & !out2;

 out0=en & r0;
 out1=en & (!r0) & r1;
 out2=en & (!r0) & (!r1) & r2;
 out3=en & (!r0) & (!r1) & (!r2) & r3;
end

endmodule
